function insertAt(arr, index, value) {
  for (let i = arr.length; i > index; i--) arr[i] = arr[i-1];
  arr[index] = value;
  return arr;
}

function deleteAt(arr, index) {
  for (let i = index; i < arr.length - 1; i++) arr[i] = arr[i+1];
  arr.pop();
  return arr;
}

