function majorityElement(nums) {
  let candidate = nums[0], votes = 1;
  for (let i = 1; i < nums.length; i++) {
    if (votes === 0) { candidate = nums[i]; votes = 1; }
    else if (nums[i] === candidate) votes++;
    else votes--;
  }
  return candidate; // guaranteed to be majority
}

