// Naive O(nm) string matching
function naiveSearch(text, pattern) {
  const n = text.length, m = pattern.length;
  const matches = [];
  for (let i = 0; i <= n - m; i++) {
    let j = 0;
    while (j < m && text[i + j] === pattern[j]) j++;
    if (j === m) matches.push(i);
  }
  return matches;
}
console.log(naiveSearch('abababc', 'aba')); // [0, 2]

