def is_palindrome(s):
    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]: return False
        l += 1; r -= 1
    return True

def longest_palindrome(s):
    start, max_len = 0, 1
    def expand(l, r):
        nonlocal start, max_len
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1; r += 1
        if r - l - 1 > max_len:
            max_len = r - l - 1; start = l + 1
    for i in range(len(s)):
        expand(i, i); expand(i, i+1)
    return s[start:start+max_len]

