code.javascript:
function rollingHash(s, patLen) {
  const BASE = 31, MOD = 1e9 + 7;
  let hash = 0, power = 1;
  const results = [];

  // Build initial window hash
  for (let i = 0; i < patLen; i++) {
    hash = (hash + (s.charCodeAt(i) - 96) * power) % MOD;
    if (i < patLen - 1) power = power * BASE % MOD;
  }
  results.push([0, hash]);

  // Slide window
  for (let i = patLen; i < s.length; i++) {
    hash = (hash - (s.charCodeAt(i - patLen) - 96) + MOD) % MOD;
    hash = hash * BASE % MOD;
    hash = (hash + (s.charCodeAt(i) - 96)) % MOD;
    results.push([i - patLen + 1, hash]);
  }
  return results;
}

code.java:
// Rolling hash for window of size k
long rollingHash(String s, int k, long base, long mod) {
    long hash = 0, power = 1;
    for (int i = 0; i < k; i++) {
        hash = (hash + (s.charAt(i) - 'a' + 1) * power) % mod;
        if (i < k-1) power = power * base % mod;
    }
    return hash;
}

code.cpp:
long long rollingHash(string& s, int k, long long base=31, long long mod=1e9+7) {
    long long hash = 0, power = 1;
    for (int i = 0; i < k; i++) {
        hash = (hash + (s[i]-'a'+1) * power) % mod;
        if (i < k-1) power = power * base % mod;
    }
    return hash;
}

