code.javascript:
function evaluate(expr) {
  const nums = [], ops = [];
  const prec = {'+': 1, '-': 1, '*': 2, '/': 2};
  const applyOp = () => {
    const b = nums.pop(), a = nums.pop(), op = ops.pop();
    if (op === '+') nums.push(a + b);
    else if (op === '-') nums.push(a - b);
    else if (op === '*') nums.push(a * b);
    else nums.push(Math.trunc(a / b));
  };
  let i = 0;
  while (i < expr.length) {
    if (expr[i] === ' ') { i++; continue; }
    if (/\d/.test(expr[i])) {
      let num = 0;
      while (i < expr.length && /\d/.test(expr[i])) num = num * 10 + +expr[i++];
      nums.push(num);
    } else {
      while (ops.length && prec[ops[ops.length-1]] >= prec[expr[i]]) applyOp();
      ops.push(expr[i++]);
    }
  }
  while (ops.length) applyOp();
  return nums[0];
}
console.log(evaluate('3 + 4 * 2')); // 11

