        nums.append(a+b if op=='+' else a-b if op=='-' else a*b if op=='*' else int(a/b))
    i = 0
    while i < len(expr):
        if expr[i] == ' ': i += 1; continue
        if expr[i].isdigit():
            num = 0
            while i < len(expr) and expr[i].isdigit(): num = num*10 + int(expr[i]); i += 1
            nums.append(num)
        else:
            while ops and prec.get(ops[-1], 0) >= prec.get(expr[i], 0): apply_op()
            ops.append(expr[i]); i += 1
    while ops: apply_op()
    return nums[0]
