def next_greater_element(nums):
    n = len(nums)
    result = [-1] * n
    stack = []  # monotonic decreasing stack of indices
    for i in range(n):
        while stack and nums[stack[-1]] < nums[i]:
            result[stack.pop()] = nums[i]
        stack.append(i)
    return result

