class Deque {
  constructor() { this.items = {}; this.front = 0; this.rear = 0; }
  pushFront(val) { this.items[--this.front] = val; }
  pushRear(val) { this.items[this.rear++] = val; }
  popFront() {
    if (this.isEmpty()) return null;
    const val = this.items[this.front];
    delete this.items[this.front++];
    return val;
  }
  popRear() {
    if (this.isEmpty()) return null;
    const val = this.items[--this.rear];
    delete this.items[this.rear];
    return val;
  }
  peekFront() { return this.items[this.front]; }
  peekRear() { return this.items[this.rear - 1]; }
  isEmpty() { return this.front === this.rear; }
  size() { return this.rear - this.front; }
}

