// Find max of unimodal discrete function f over [lo, hi]
function ternarySearchMax(f, lo, hi) {
  while (hi - lo > 2) {
    const m1 = lo + Math.floor((hi - lo) / 3);
    const m2 = hi - Math.floor((hi - lo) / 3);
    if (f(m1) < f(m2)) lo = m1 + 1;
    else hi = m2 - 1;
  }
  // Linear scan the remaining few elements
  let best = lo;
  for (let i = lo + 1; i <= hi; i++) if (f(i) > f(best)) best = i;
  return best;
}

