// Simplified Tim Sort concept (real implementation is complex)
const MIN_RUN = 32;

function insertionSort(arr, lo, hi) {
  for (let i = lo + 1; i <= hi; i++) {
    const key = arr[i];
    let j = i - 1;
    while (j >= lo && arr[j] > key) { arr[j+1] = arr[j]; j--; }
    arr[j+1] = key;
  }
}

function timSort(arr) {
  const n = arr.length;
  // Sort runs of MIN_RUN using insertion sort
  for (let i = 0; i < n; i += MIN_RUN) {
    insertionSort(arr, i, Math.min(i + MIN_RUN - 1, n - 1));
  }
  // Merge sorted runs
  for (let size = MIN_RUN; size < n; size *= 2) {
    for (let lo = 0; lo < n; lo += 2 * size) {
      const mid = Math.min(lo + size - 1, n - 1);
      const hi = Math.min(lo + 2 * size - 1, n - 1);
      if (mid < hi) merge(arr, lo, mid, hi);
    }
  }
  return arr;
}

