            if i == 0: result.append(node.val)
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
    return result

def right_view(root):
    if not root: return []
    result, queue = [], deque([root])
    while queue:
        for i in range(size := len(queue)):
            node = queue.popleft()
            if i == size - 1: result.append(node.val)
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
    return result

