class XORTrieNode {
  constructor() { this.children = [null, null]; }
}

class XORTrie {
  constructor() { this.root = new XORTrieNode(); }

  insert(num) {
    let node = this.root;
    for (let bit = 31; bit >= 0; bit--) {
      const b = (num >> bit) & 1;
      if (!node.children[b]) node.children[b] = new XORTrieNode();
      node = node.children[b];
    }
  }

  maxXOR(num) {
    let node = this.root, xor = 0;
    for (let bit = 31; bit >= 0; bit--) {
      const b = (num >> bit) & 1;
      const want = 1 - b; // we want the opposite bit for max XOR
      if (node.children[want]) { xor |= (1 << bit); node = node.children[want]; }
      else if (node.children[b]) node = node.children[b];
      else break;
    }
    return xor;
  }
}

