        for bit in range(31, -1, -1):
            b = (num >> bit) & 1
            if not node.children[b]: node.children[b] = XORTrieNode()
            node = node.children[b]

    def max_xor(self, num):
        node, xor = self.root, 0
        for bit in range(31, -1, -1):
            b = (num >> bit) & 1
            want = 1 - b
            if node.children[want]: xor |= (1 << bit); node = node.children[want]
            elif node.children[b]: node = node.children[b]
            else: break
        return xor

